import{_ as r,C as s,o,c as n,aj as d,E as e}from"./framework.js";const k=JSON.parse('{"title":"IndexedDB 表 | Cms / Database | Documentation","description":"IndexedDB 表是站点自带的 动态表 存储：在后台定义表名与字段（列）后，可在本页维护数据，并在 KScript 中通过 k.DB.indexedDb.[表名] 读写。数据按站点隔离，无需单独配置连接字符串。","frontmatter":{"title":"IndexedDB 表 | Cms / Database | Documentation","description":"IndexedDB 表是站点自带的 动态表 存储：在后台定义表名与字段（列）后，可在本页维护数据，并在 KScript 中通过 k.DB.indexedDb.[表名] 读写。数据按站点隔离，无需单独配置连接字符串。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/database/table.html"}]]},"headers":[],"relativePath":"zh/cms/database/table.md","filePath":"cms/database/table.md","lastUpdated":1780650820000}'),i={name:"zh/cms/database/table.md"};function l(h,t,g,b,c,p){const a=s("DocImage");return o(),n("div",null,[t[0]||(t[0]=d('<h1 id="indexeddb-表" tabindex="-1">IndexedDB 表 <a class="header-anchor" href="#indexeddb-表" aria-label="Permalink to &quot;IndexedDB 表&quot;">​</a></h1><blockquote><p>菜单：<strong>数据库 → IndexedDB 表</strong><br> 深链：<code>/_Admin/database/table?SiteId={站点GUID}</code></p></blockquote><p><strong>IndexedDB 表</strong>是站点自带的 <strong>动态表</strong> 存储：在后台定义表名与字段（列）后，可在本页维护数据，并在 KScript 中通过 <strong><code>k.DB.indexedDb.{表名}</code></strong> 读写。数据按站点隔离，无需单独配置连接字符串。</p><div class="tip custom-block"><p class="custom-block-title">权限</p><p>列表与浏览数据：<code>database</code>（查看）。<strong>创建表</strong>、改列、增删改数据需 <code>database·edit</code>；多选删除表或删除数据行需 <code>database·delete</code>。</p></div><div class="info custom-block"><p class="custom-block-title">与 SQLite / MySQL 等菜单的区别</p><table tabindex="0"><thead><tr><th></th><th><strong>IndexedDB 表</strong></th><th><strong>SQLite 表</strong> 等</th></tr></thead><tbody><tr><td>存储</td><td>站点 IndexedDB 动态表</td><td>站点 SQLite 文件或外部数据库连接</td></tr><tr><td>建表</td><td>后台填表名即可</td><td>SQLite 开箱即用；MySQL/SQL Server 须先配连接</td></tr><tr><td>改结构</td><td><strong>列设置</strong> 页维护字段</td><td>多数为已有物理表，能力以界面为准</td></tr><tr><td>脚本</td><td><code>k.DB.indexedDb.表名</code></td><td><code>k.DB.sqlite</code> 等</td></tr></tbody></table><p>详见 <a href="./">数据库概述</a>。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>数据库 → IndexedDB 表</strong>。</li><li>左侧 <strong>数据库 → IndexedDB 表</strong>。</li></ol>',7)),e(a,{src:"/cms/database/table-overview.png",alt:"IndexedDB 表列表",width:"1120"}),t[1]||(t[1]=d('<h2 id="表列表" tabindex="-1">表列表 <a class="header-anchor" href="#表列表" aria-label="Permalink to &quot;表列表&quot;">​</a></h2><h3 id="工具栏" tabindex="-1">工具栏 <a class="header-anchor" href="#工具栏" aria-label="Permalink to &quot;工具栏&quot;">​</a></h3><table tabindex="0"><thead><tr><th>按钮</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><strong>创建表</strong></td><td><code>database·edit</code></td><td>打开 <a href="#创建表弹窗">创建表弹窗</a></td></tr></tbody></table>',3)),e(a,{src:"/cms/database/table-toolbar.png",alt:"表列表工具栏",width:"1120"}),t[2]||(t[2]=d('<h3 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to &quot;列表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>列 / 操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>名称</strong></td><td>点击表名进入 <a href="#表数据">表数据</a></td></tr><tr><td>行末 <strong>设置</strong>（齿轮）</td><td>进入 <a href="#列设置">列设置</a></td></tr><tr><td>多选 <strong>删除</strong></td><td>删除整张表及其数据（<code>database·delete</code>）</td></tr></tbody></table><p>列表中不显示以 <code>_sys_</code>、<code>_koobootemp</code> 开头的系统内部表名。</p>',3)),e(a,{src:"/cms/database/table-list.png",alt:"表列表",width:"1120"}),t[3]||(t[3]=d('<h3 id="创建表弹窗" tabindex="-1">创建表弹窗 <a class="header-anchor" href="#创建表弹窗" aria-label="Permalink to &quot;创建表弹窗&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>规则</th></tr></thead><tbody><tr><td><strong>表名</strong></td><td>必填；1～50 字符；字母或数字开头；仅允许字母与数字；站点内唯一</td></tr></tbody></table><p>确认后注册表定义，即可进入 <strong>列设置</strong> 添加字段，或点击表名直接维护数据（空表也可先写入数据，列会随 <strong>列设置</strong> 保存生效）。</p>',3)),e(a,{src:"/cms/database/table-create-dialog.png",alt:"创建表弹窗",width:"1120"}),t[4]||(t[4]=d('<h2 id="列设置" tabindex="-1">列设置 <a class="header-anchor" href="#列设置" aria-label="Permalink to &quot;列设置&quot;">​</a></h2><p>路径：<code>/_Admin/database/table/columns?SiteId=...&amp;table={表名}</code></p><p>从列表 <strong>设置</strong> 进入，或在 <strong>表数据</strong> 页工具栏 <strong>设置</strong> 进入。页头显示当前表名。</p><h3 id="工具栏-1" tabindex="-1">工具栏 <a class="header-anchor" href="#工具栏-1" aria-label="Permalink to &quot;工具栏&quot;">​</a></h3><table tabindex="0"><thead><tr><th>按钮</th><th>说明</th></tr></thead><tbody><tr><td><strong>新建列</strong></td><td>打开 <a href="#列编辑弹窗">列编辑弹窗</a></td></tr></tbody></table><h3 id="列列表" tabindex="-1">列列表 <a class="header-anchor" href="#列列表" aria-label="Permalink to &quot;列列表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td><strong>列名</strong></td><td>字段名</td></tr><tr><td><strong>控件类型</strong></td><td>见下表</td></tr><tr><td><strong>主键</strong> / <strong>唯一</strong></td><td>仅 IndexedDB 表显示</td></tr><tr><td><strong>索引</strong></td><td>是否建索引（主键列视为已索引）</td></tr><tr><td><strong>编辑</strong> / <strong>删除</strong></td><td>改列定义；从列表移除列（保存后生效）</td></tr></tbody></table><p>底部 <strong>保存</strong> / <strong>取消</strong>：<strong>保存</strong> 将整表列定义写回站点；离开页面前若有未保存修改会提示。内部字段 <strong><code>_id</code></strong>（主键）、<strong><code>_version</code></strong> 不在列表中展示。</p>',8)),e(a,{src:"/cms/database/table-columns.png",alt:"列设置列表",width:"1120"}),t[5]||(t[5]=d('<h3 id="列编辑弹窗" tabindex="-1">列编辑弹窗 <a class="header-anchor" href="#列编辑弹窗" aria-label="Permalink to &quot;列编辑弹窗&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>名称</strong></td><td>新建必填；保存后不可改名</td></tr><tr><td><strong>控件类型</strong></td><td>决定数据类型与录入控件（见下）</td></tr><tr><td><strong>长度</strong></td><td>文本类控件可设最大长度</td></tr><tr><td><strong>选项</strong></td><td><strong>下拉 / 复选 / 单选</strong> 需配置显示名与值</td></tr><tr><td><strong>自增</strong></td><td>仅 <strong>数字</strong> 类型：勾选后按种子、步长递增；编辑数据时不可改</td></tr><tr><td><strong>主键</strong></td><td>业务主键标记（与系统 <code>_id</code> 并存，按表设计使用）</td></tr><tr><td><strong>唯一</strong></td><td>列值唯一</td></tr><tr><td><strong>索引</strong></td><td>查询索引</td></tr></tbody></table><table tabindex="0"><thead><tr><th>控件类型（界面）</th><th>典型用途</th></tr></thead><tbody><tr><td>文本框</td><td>短文本</td></tr><tr><td>多行文本</td><td>长文本</td></tr><tr><td>富文本</td><td>HTML 内容</td></tr><tr><td>下拉 / 复选框 / 单选</td><td>枚举选项</td></tr><tr><td>布尔</td><td>是/否</td></tr><tr><td>日期时间</td><td>日期时间</td></tr><tr><td>数字</td><td>数值、可自增</td></tr></tbody></table>',3)),e(a,{src:"/cms/database/table-column-dialog.png",alt:"列编辑弹窗",width:"1120"}),t[6]||(t[6]=d('<h2 id="表数据" tabindex="-1">表数据 <a class="header-anchor" href="#表数据" aria-label="Permalink to &quot;表数据&quot;">​</a></h2><p>路径：<code>/_Admin/database/table/data?SiteId=...&amp;table={表名}</code></p><p>点击列表中的 <strong>表名</strong> 进入。</p><h3 id="工具栏-2" tabindex="-1">工具栏 <a class="header-anchor" href="#工具栏-2" aria-label="Permalink to &quot;工具栏&quot;">​</a></h3><table tabindex="0"><thead><tr><th>按钮</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><strong>新建数据</strong></td><td><code>database·edit</code></td><td>进入 <a href="#编辑数据">编辑数据</a>（新建）</td></tr><tr><td><strong>导出数据</strong></td><td><code>database</code>（查看）</td><td>导出当前筛选排序下的数据为 <strong>CSV</strong></td></tr><tr><td><strong>设置</strong></td><td>—</td><td>跳转 <strong>列设置</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">无 CSV 导入</p><p><strong>IndexedDB 表</strong> 数据页 <strong>不提供</strong>「导入数据」按钮（该功能在 SQLite / MySQL / SQL Server 表菜单中提供）。批量写入请用脚本 <code>k.DB.indexedDb</code> 或自行开发导入逻辑。</p></div>',6)),e(a,{src:"/cms/database/table-data-toolbar.png",alt:"表数据工具栏",width:"1120"}),t[7]||(t[7]=d('<h3 id="数据表格" tabindex="-1">数据表格 <a class="header-anchor" href="#数据表格" aria-label="Permalink to &quot;数据表格&quot;">​</a></h3><ul><li>列：除 <strong><code>_id</code></strong>、<strong><code>_version</code></strong> 外的业务字段；表头可 <strong>排序</strong>（排序状态会记住到浏览器本地）。</li><li>分页：默认每页 <strong>30</strong> 条，可翻页。</li><li>行末 <strong>编辑</strong>：进入 <a href="#编辑数据">编辑数据</a>。</li><li>多选 <strong>删除</strong>：按主键删除行（<code>database·delete</code>）。</li></ul><p>日期时间列在列表中会格式化为本地时间显示。</p>',3)),e(a,{src:"/cms/database/table-data.png",alt:"表数据列表",width:"1120"}),t[8]||(t[8]=d(`<h2 id="编辑数据" tabindex="-1">编辑数据 <a class="header-anchor" href="#编辑数据" aria-label="Permalink to &quot;编辑数据&quot;">​</a></h2><p>路径：<code>/_Admin/database/table/edit-data?SiteId=...&amp;table={表名}</code>（新建无 <code>id</code>；编辑带 <code>id</code>）</p><p>按 <strong>列设置</strong> 中的控件类型渲染表单项：文本、富文本、选项、布尔、日期时间、数字等。<strong>自增</strong> 字段仅展示当前值，不可修改。</p><p><strong>保存</strong> 后返回 <strong>表数据</strong> 列表；<strong>取消</strong> 放弃并返回。</p><h2 id="脚本访问-开发" tabindex="-1">脚本访问（开发） <a class="header-anchor" href="#脚本访问-开发" aria-label="Permalink to &quot;脚本访问（开发）&quot;">​</a></h2><p>在 Code / 模块等服务端脚本中，表名作为 <code>k.DB.indexedDb</code> 的属性访问，例如：</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> row</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> k.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.indexedDb.orders.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;orderNo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A1001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">k.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.indexedDb.orders.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ orderNo: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A1002&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, amount: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">99</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p>链式 API（<code>find</code> / <code>findAll</code> / <code>add</code> / <code>update</code> / <code>delete</code> / <code>pagination</code> 等）见 <strong><a href="/kb-docs/zh/api/indexed-db/">k.DB.indexedDb</a></strong>。后台在本页所做的列与数据变更，与脚本读写同一张表。</p><div class="tip custom-block"><p class="custom-block-title">SQL 日志</p><p>IndexedDB 操作 <strong>不会</strong> 写入 SQL 日志。仅 <code>k.DB.sqlite</code> / MySQL / SQL Server 的 SQL 在开启站点 <strong>SQL 日志</strong> 后可于 <a href="./sql-logs.html">SQL 日志</a> 查看。</p></div><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><ol><li><strong>创建表</strong>，填写合法表名。</li><li>打开 <strong>设置</strong>，<strong>新建列</strong> 并 <strong>保存</strong> 列定义。</li><li>点击表名，<strong>新建数据</strong> 录入或通过脚本写入。</li><li>需要关联多表时，配置 <a href="./table-relation.html">IndexedDB 表关系</a>。</li><li>排障或审计时查看 <a href="./sql-logs.html">SQL 日志</a>。</li></ol><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./">数据库概述</a></td><td>子菜单与路由</td></tr><tr><td><a href="./table-relation.html">IndexedDB 表关系</a></td><td>表间关联</td></tr><tr><td><a href="/kb-docs/zh/api/indexed-db/">k.DB.indexedDb</a></td><td>脚本 API 全文</td></tr><tr><td><a href="./../development/code.html">开发 · 代码</a></td><td>编写调用表的 Code</td></tr></tbody></table>`,13))])}const m=r(i,[["render",l]]);export{k as __pageData,m as default};
